import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial, Vector2, Color } from 'three/webgpu';
import { uv, texture, position, normal, uniform, add, mul, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // Geometry dimensions (thin rule aspect)
  const width = 2.0;
  const height = 0.4;
  const geometry = new PlaneGeometry(width, height, 64, 64);

  // Placeholder textures (1x1 black)
  const placeholderColorTex = new ctx.THREE.Texture();
  const placeholderDepthTex = new ctx.THREE.Texture();

  // TSL uniforms for dynamic texture updates
  const colorUniform = uniform(placeholderColorTex);
  const depthUniform = uniform(placeholderDepthTex);
  const displacementScale = uniform(0.05);

  // Displacement node: offset vertices along normal using depth map
  const depthSample = texture(depthUniform, uv()).r;
  const displacement = depthSample.mul(displacementScale);
  const displacedPosition = position.add(normal.mul(displacement));

  // Color node from texture
  const colorNode = texture(colorUniform, uv());

  // Material
  const material = new MeshBasicNodeMaterial({
    colorNode,
    positionNode: displacedPosition,
    side: ctx.THREE.DoubleSide,
  });

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Asynchronous texture loaders
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.wrapS = tex.wrapT = ctx.THREE.ClampToEdgeWrapping;
    colorUniform.value = tex;
    material.needsUpdate = true;
  }).catch(() => {});

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      tex.wrapS = tex.wrapT = ctx.THREE.ClampToEdgeWrapping;
      depthUniform.value = tex;
      material.needsUpdate = true;
    }).catch(() => {});
  }

  // --- Interaction handlers ---

  // Hover lift (preset: rise-in)
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(group.position, {
    y: 0.15,
    duration: 0.5,
    ease: 'power3.out',
  }, 0);

  const handleMouseEnter = () => {
    hoverTimeline.play();
  };
  const handleMouseLeave = () => {
    hoverTimeline.reverse();
  };
  const handleClick = () => {
    ctx.emit('hub-features.select');
  };

  // Attach to userData
  group.userData.handlers = {
    mouseenter: handleMouseEnter,
    mouseleave: handleMouseLeave,
    click: handleClick,
  };

  // --- Cinematic primitive: magnetic-cursor for parallax ---
  let primitiveCleanup = () => {};
  if (ctx.primitives && ctx.primitives['magnetic-cursor']) {
    try {
      const result = ctx.primitives['magnetic-cursor'](mesh, {
        strength: 0.02,
        influenceRadius: 10,
        trigger: 'hover', // reacts to cursor proximity
      });
      primitiveCleanup = result?.cleanup || (() => {});
    } catch (e) {
      console.warn('magnetic-cursor primitive failed:', e);
    }
  }

  // --- Cleanup ---
  group.userData.cleanup = () => {
    hoverTimeline.kill();
    primitiveCleanup();
    geometry.dispose();
    material.dispose();

    // Dispose loaded textures if any
    if (colorUniform.value && colorUniform.value !== placeholderColorTex) {
      colorUniform.value.dispose();
    }
    if (depthUniform.value && depthUniform.value !== placeholderDepthTex) {
      depthUniform.value.dispose();
    }
    placeholderColorTex.dispose();
    placeholderDepthTex.dispose();
  };

  return group;
}
